function aggregateGear(gear){const fields=['attack_stab','attack_slash','attack_crush','attack_magic','attack_ranged','defence_stab','defence_slash','defence_crush','defence_magic','defence_ranged','melee_strength','ranged_strength','magic_damage_percent','prayer_bonus'];return fields.reduce((result,key)=>(result[key]=Object.values(gear||{}).reduce((sum,item)=>sum+Number(item?.[key]||0),0),result),{})}
function gearDps(){const stats=aggregateGear(state.gearLab.current),style=state.gearLab.combatStyle||'melee',target=Math.max(1,Number(state.gearLab.targetDefence)||100);let level,attackBonus,maxHit,speed=4;if(style==='ranged'){level=skill('Ranged')?.current||1;attackBonus=stats.attack_ranged;maxHit=Math.floor(.5+(level+8)*(stats.ranged_strength+64)/640)}else if(style==='magic'){level=skill('Magic')?.current||1;attackBonus=stats.attack_magic;maxHit=Math.floor((Number(state.gearLab.spellMaxHit)||20)*(1+stats.magic_damage_percent/100))}else{level=skill('Attack')?.current||1;const strength=skill('Strength')?.current||1;attackBonus=Math.max(stats.attack_stab,stats.attack_slash,stats.attack_crush);maxHit=Math.floor(.5+(strength+8)*(stats.melee_strength+64)/640)}const weapon=state.gearLab.current.weapon,speedTicks=Number(weapon?.attack_speed_ticks)||speed,attackRoll=(level+8)*(attackBonus+64),defenceRoll=target*64,hitChance=attackRoll>defenceRoll?1-(defenceRoll+2)/(2*(attackRoll+1)):attackRoll/(2*(defenceRoll+1)),dps=Math.max(0,hitChance*maxHit/2/(speedTicks*.6));return {stats,maxHit,hitChance,dps,speedTicks}}
function gearItemImage(item){return item?`<img src="https://static.runelite.net/cache/item/icon/${item.exact_osrs_item_id}.png" alt="" loading="lazy">`:''}
function gearSlotsMarkup(){return `<div class="gear-mannequin"><div class="mannequin-silhouette">♟</div>${gearSlots.map(([slot,label,icon],index)=>{const item=state.gearLab.current[slot];return `<button class="gear-slot slot-${slot} ${ui.gearSlot===slot?'active':''}" data-gear-slot="${slot}" title="${label}">${item?gearItemImage(item):`<span>${icon}</span>`}<small>${item?esc(item.exact_osrs_item_name):label}</small></button>`}).join('')}</div>`}
function gearStats(){const {stats,maxHit,hitChance,dps,speedTicks}=gearDps();return `<div class="gear-stat-grid"><div><small>Max hit</small><strong>${maxHit}</strong></div><div><small>Precisão</small><strong>${Math.round(hitChance*100)}%</strong></div><div><small>DPS básico</small><strong>${dps.toFixed(2)}</strong></div><div><small>Velocidade</small><strong>${speedTicks} ticks</strong></div><div><small>Str</small><strong>${stats.melee_strength>=0?'+':''}${stats.melee_strength}</strong></div><div><small>Ranged str</small><strong>${stats.ranged_strength>=0?'+':''}${stats.ranged_strength}</strong></div><div><small>Magic dmg</small><strong>${stats.magic_damage_percent}%</strong></div><div><small>Prayer</small><strong>+${stats.prayer_bonus}</strong></div></div>`}
function filteredGearItems(){const aliases=ui.gearSlot==='weapon'?['weapon','2h']:ui.gearSlot==='shield'?['shield']:[ui.gearSlot],query=ui.gearSearch.toLowerCase();return equipmentData.filter(item=>aliases.includes(item.equipment_slot)).filter(item=>!query||item.exact_osrs_item_name.toLowerCase().includes(query)).slice(0,ui.gearLimit)}
