function gearComparison(){const preset=state.gearLab.presets.find(item=>item.id===ui.gearCompareId);if(!preset)return '';const current=gearDps(),savedGear=state.gearLab.current;state.gearLab.current=preset.gear;const previous=gearDps();state.gearLab.current=savedGear;return `<div class="gear-comparison"><h3>Comparação com ${esc(preset.name)}</h3><div><span>DPS</span><strong>${previous.dps.toFixed(2)} → ${current.dps.toFixed(2)}</strong><em class="${current.dps>=previous.dps?'positive':'negative'}">${current.dps>=previous.dps?'+':''}${(current.dps-previous.dps).toFixed(2)}</em></div><div><span>Max hit</span><strong>${previous.maxHit} → ${current.maxHit}</strong></div></div>`}

